#include <stdio.h>

int main() {
    int v;
    int contas[3];

    if (scanf("%d", &v) != 1) return 0;
    if (scanf("%d", &contas[0]) != 1) return 0;
    if (scanf("%d", &contas[1]) != 1) return 0;
    if (scanf("%d", &contas[2]) != 1) return 0;

    // Ordenação simples de 3 elementos
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (contas[i] > contas[j]) {
                int temp = contas[i];
                contas[i] = contas[j];
                contas[j] = temp;
            }
        }
    }

    int pagas = 0;
    for (int i = 0; i < 3; i++) {
        if (v >= contas[i]) {
            v -= contas[i];
            pagas++;
        } else {
            break;
        }
    }

    printf("%d\n", pagas);

    return 0;
}
